import hashlib

BLOCK = 4 * 1024 * 1024   # 4 MB, Dropbox's block size

def blocklist(path: str) -> list[str]:
    hashes = []
    with open(path, "rb") as f:
        while chunk := f.read(BLOCK):
            hashes.append(hashlib.sha256(chunk).hexdigest())  # content = identity
    return hashes

def upload(ns: str, path: str, base_version: int) -> int:
    hashes = blocklist(path)
    while True:
        r = meta.commit(ns, path, hashes, base_version=base_version)
        if r.status == "need_blocks":            # send only blocks the server lacks
            for h in r.missing:
                block_server.put(h, read_block(path, hashes.index(h)))
        elif r.status == "conflict":             # someone committed since base_version
            return save_conflicted_copy(ns, path, hashes)   # binary can't merge: keep both
        else:
            return r.version                     # journal entry written; others get notified

def pull(ns: str, cursor: str) -> str:
    changes, cursor = meta.list(ns, cursor)      # only journal entries after our cursor
    for c in changes:
        for h in c.blocks:
            if not local_blocks.has(h):          # dedup on the way down, too
                local_blocks.put(h, block_server.get(h))
        write_atomically(c.path, [local_blocks.get(h) for h in c.blocks])
    return cursor
